let storageAvailable=true;
function readState(){try{const s=JSON.parse(localStorage.getItem(STORAGE_KEY)||'{}');return {theme:['light','dark'].includes(s.theme)?s.theme:document.documentElement.dataset.theme||'light',mode:['zh','en','ja','both'].includes(s.mode)?s.mode:'zh',read:Array.isArray(s.read)?s.read:[],attempts:s.attempts&&typeof s.attempts==='object'?s.attempts:{},lastLesson:typeof s.lastLesson==='string'?s.lastLesson:null,sourceOpen:s.sourceOpen===true,anchors:s.anchors&&typeof s.anchors==='object'?s.anchors:{}};}catch{storageAvailable=false;return {theme:document.documentElement.dataset.theme||'light',mode:'zh',read:[],attempts:{},lastLesson:null,sourceOpen:false,anchors:{}};}}
const state=readState();
let japanesePhrases={},japaneseNames={},japaneseLocaleRequest;
const text=(zh,en,ja)=>state.mode==='ja'?(ja??JA_UI[zh]??japanesePhrases[en]??en):state.mode==='en'?en:zh;
async function loadJapaneseLocale(){
 if(!japaneseLocaleRequest)japaneseLocaleRequest=(async()=>{const response=await fetch(new URL('./locales/ja.json',import.meta.url),{cache:'no-cache'});if(!response.ok)throw new Error('Japanese locale unavailable');const pack=await response.json();japanesePhrases=pack.phrases;japaneseNames=pack.names||{};})().catch(error=>{japaneseLocaleRequest=null;throw error;});
 return japaneseLocaleRequest;
}
const t=(key,n)=>text(...(labels[key]||[key,key])).replace('{n}',String(n??''));
