function stationStatus(c,path){
 const values=[];
 if(c.complete)values.push(text('已完成','Completed','読了'));
 if(c.id===path.last?.chapter)values.push(text('目前位置','Current','現在地'));
 if(c.id===path.next?.chapter)values.push(text('下一站','Next stop','次の駅'));
 return values.join(' · ');
}
function connectedRoute(path,compact=false){
 const layout=routeGeometry(path.stages,compact);
 const arrows=layout.edges.map(edge=>{const a=layout.nodes.find(n=>n.chapter.id===edge.from),b=layout.nodes.find(n=>n.chapter.id===edge.to);let x=(a.x+b.x)/2,y=(a.y+b.y)/2,angle=compact?90:b.row===a.row?(b.x>a.x?0:180):90;if(!compact&&a.row!==b.row)x=a.x+(a.row%2?-45:45);return `<path class="route-direction ${edge.complete?'edge-done':''}" d="M-4 -4 L2 0 L-4 4" transform="translate(${x} ${y}) rotate(${angle})"/>`;}).join('');
 return `<svg class="connected-map ${compact?'compact-route':'wide-route'}" viewBox="0 0 ${layout.width} ${layout.height}" role="group" aria-label="${text('20 章串連學習路線圖','Connected route through all 20 chapters','全20章を結ぶ学習ルート')}"><g aria-hidden="true">${layout.edges.map(edge=>`<path class="route-connection ${edge.complete?'edge-done':''}" data-edge-from="${edge.from}" data-edge-to="${edge.to}" d="${edge.d}"/>`).join('')}${arrows}${path.stages.map((stage,i)=>{const first=layout.nodes.find(n=>n.stage===stage);return `<text class="map-stage-label" x="${compact?20:18}" y="${first.y-(compact?43:55)}">${text('階段','Stage','段階')} ${i+1} · ${esc(text(...stage.title))}</text>`;}).join('')}</g>${layout.nodes.map(node=>{
 const c=node.chapter,current=c.id===path.last?.chapter,next=c.id===path.next?.chapter,status=stationStatus(c,path),lines=wrapMapLabel(chapterTitle(c),compact?16:(state.mode==='en'?18:12)),tx=compact?83:node.x,ty=compact?node.y+5:node.y+61;
 return `<a class="route-node ${c.complete?'node-done':''} ${current?'node-current':''} ${next?'node-next':''}" href="${lessonHref(c.nextId)}" data-map-node="${c.id}" ${current?'aria-current="step"':''} aria-label="${esc(`${chapterLabel(c.id)} ${chapterTitle(c)} ${status} ${c.readCount}/${c.sectionIds.length}`)}"><title>${esc(`${chapterLabel(c.id)} · ${chapterTitle(c)} · ${status}`)}</title><circle class="node-hit-area" cx="${node.x}" cy="${node.y}" r="34"/><circle class="node-current-ring" cx="${node.x}" cy="${node.y}" r="30"/><circle class="node-disc" cx="${node.x}" cy="${node.y}" r="22"/><text class="node-number" x="${node.x}" y="${node.y+5}" text-anchor="middle">${c.complete?'✓':String(c.id).padStart(2,'0')}</text>${next?`<path class="node-next-pin" d="M${node.x-5} ${node.y-38}h10l-5 7z"/>`:''}<text class="map-chapter-label" x="${tx}" y="${compact?node.y-17:node.y+43}" text-anchor="${compact?'start':'middle'}">${chapterLabel(c.id)} · ${c.readCount}/${c.sectionIds.length}</text><text class="map-node-title" x="${tx}" y="${ty}" text-anchor="${compact?'start':'middle'}">${lines.map((line,i)=>`<tspan x="${tx}" dy="${i?18:0}">${esc(line)}</tspan>`).join('')}</text><text class="map-node-status" x="${tx}" y="${ty+lines.length*18+5}" text-anchor="${compact?'start':'middle'}">${wrapMapLabel(status,compact?30:state.mode==='en'?22:14).map((line,i)=>`<tspan x="${tx}" dy="${i?14:0}">${esc(line)}</tspan>`).join('')}</text></a>`;
 }).join('')}</svg>`;
}
function learningMap(){
 const path=buildLearningPath(data.chapters,data.lessons,state.read,state.lastLesson),completed=path.stages.flatMap(s=>s.items).filter(c=>c.complete).length;
 return `<div class="page transit-page"><header class="transit-heading"><p class="eyebrow">THE BAYES ROUTE MAP</p><h1>${text('每一章，都是一個前進的節點。','Every chapter is a stop on your journey.','一つひとつの章が、学びの駅になる。')}</h1><p>${text('沿著連線依原書順序前進，也能點選任何節點自由探索。完成以「全章小節已讀」判定。雙環記錄上次開啟的章節，小旗依原書順序指出第一個未讀小節；測驗成績另計。','Follow the connections in book order, or select any station. A chapter is complete when all its sections are read. The double ring marks your last-opened chapter; the pennant points to the first unread section in book order. Quiz scores are separate.','線に沿って原書の順に進んでも、好きな駅を選んでもかまいません。全節の既読で章の読了を判定します。二重の輪は前回開いた章、小旗は原書の順で最初の未読の節を示します。問題の成績は別に記録します。')}</p></header><section class="route-status-strip" aria-label="${text('路線狀態','Route status','ルートの状態')}"><div><span class="status-key done-key">${text('已完成','Completed','読了')}</span><strong>${completed} / 20 ${text('章','chapters','章')}</strong><small>${path.readCount} / 195 ${text('小節已讀','sections read','節が既読')}</small></div><div><span class="status-key current-key">${text('目前位置','Current position','現在地')}</span><strong>${path.last?chapterLabel(path.last.chapter):text('尚未開始','Not started','未開始')}</strong><small>${path.last?esc(lessonTitle(path.last)):text('開啟一節，留下閱讀位置','Open a section to set your position','節を開くと現在地が記録されます')}</small></div><div><span class="status-key next-key">${text('下一站','Next stop','次の駅')}</span><strong>${path.next?chapterLabel(path.next.chapter):text('全書已讀完','Route complete','全章読了')}</strong><small>${path.next?esc(lessonTitle(path.next)):text('可以回到練習複習','Return to practice for review','問題で復習しましょう')}</small></div></section><div class="route-map-toolbar"><p>${text('實心打勾＝已完成　雙環＝目前位置　小旗＝下一站','Filled check = completed · Double ring = current · Pennant = next','チェック入り＝読了　　二重の輪＝現在地　　小旗＝次の駅')}</p><a class="primary-button" href="${path.next?lessonHref(path.next.id):'#/progress'}">${path.next?text('前往下一個未讀小節','Go to the next unread section','次の未読の節へ'):text('查看學習紀錄','View learning record','学習記録を見る')}</a></div><div class="map-locate-controls"><button class="secondary-button" data-locate-node="${path.last?.chapter||''}" ${path.last?'':'disabled'}>${text('定位目前位置','Locate current station','現在地を表示')}</button><button class="secondary-button" data-locate-node="${path.next?.chapter||''}" ${path.next?'':'disabled'}>${text('定位下一站','Locate next station','次の駅を表示')}</button></div><div class="transit-canvas">${connectedRoute(path)}${connectedRoute(path,true)}</div><div class="route-stage-goals">${path.stages.map((stage,i)=>`<details><summary>${text('階段','Stage','段階')} ${i+1} · ${esc(text(...stage.title))}<span>${stage.readCount}/${stage.total}</span></summary><p>${esc(text(...stage.goal))}</p><p><strong>${text('目標：','Goal: ','目標：')}</strong>${esc(text(...stage.milestone))}</p></details>`).join('')}</div><p class="map-source-link">Think Bayes · Allen B. Downey · <a href="#/">${text('原書、作者與資料出處','Book, author and sources','原書・著者・出典')}</a></p></div>`;
}

function bindConnectedMap(){
 document.querySelectorAll('[data-locate-node]').forEach(button=>button.addEventListener('click',()=>{
  const layout=matchMedia('(max-width:960px)').matches?'.compact-route':'.wide-route';
  const target=document.querySelector(`${layout} [data-map-node="${button.dataset.locateNode}"]`);
  if(target){target.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});target.focus({preventScroll:true});}
 }));
}
function bilingual(v){if(!v)return '';if(state.mode==='both')return `<div class="bilingual-block"><p lang="zh-Hant">${esc(v.zh)}</p><p class="en-text" lang="en">${esc(v.en)}</p></div>`;return `<p lang="${state.mode==='en'?'en':state.mode==='ja'?'ja':'zh-Hant'}">${esc(text(v.zh,v.en))}</p>`;}
function sourcePanel(l,loaded=false){
 const open=state.sourceOpen===true;
 return `<section id="source-panel" class="source-panel content-block ${open?'expanded':'collapsed'}" data-block-id="source"><div class="source-summary"><h2>${icon('book')} ${t('source')}</h2><button id="source-toggle" class="source-close-button" aria-expanded="${open}" aria-controls="source-body">${open?text('✕ 關閉原文','✕ Close original'):text('展開原文','Open original')}</button></div><div id="source-body" ${open?'':'hidden'}><p class="source-instructions">${t('sourceNote')} ${text('可按上方關閉，或按 Esc 收合。','Use Close above, or press Esc to collapse.')}</p><div class="pdf-toolbar"><div class="page-navigation"><button id="pdf-prev" aria-label="${esc(t('pagePrev'))}">‹</button><label>${t('printPage')} <input type="number" min="1" max="304" id="pdf-page-input" value="${pdfPageNumber-16}" aria-label="${esc(t('printPage'))}"></label><button id="pdf-next" aria-label="${esc(t('pageNext'))}">›</button></div><a id="open-source-pdf" href="./assets/think-bayes-2e.pdf#page=${pdfPageNumber}" target="_blank" rel="noopener">${t('openPdf')}</a></div><div id="pdf-canvas-host" class="pdf-canvas-host">${loaded?'<canvas id="pdf-canvas" role="img" aria-label="'+esc(text(`原書印刷頁 ${pdfPageNumber-16}`,`Original book page ${pdfPageNumber-16}`))+'"></canvas>':`<button id="load-source" class="secondary-button source-load-button">${icon('book')}${t('loadSource')}</button>`}</div><div id="pdf-status" class="pdf-status" role="status">${loaded?t('loadingPdf'):text('按需載入原書，第一次約需下載 19 MB。','Load on demand; the first load is about 19 MB.')}</div></div></section>`;
}
function markdownHtml(md){
 const maths=[];
 const protectedMd=String(md).replace(/```[\s\S]*?```|\$\$[\s\S]*?\$\$|\$[^\n$]+?\$/g,raw=>{
  if(raw.startsWith('```'))return raw;
  const display=raw.startsWith('$$'),tex=raw.slice(display?2:1,display?-2:-1);
  if(/^\d[\d, .]*$/.test(tex)||(!display&&/[\u3040-\u30ff\u3400-\u9fff]/u.test(tex)&&!tex.includes('\\text')))return raw;
  const n=maths.length;maths.push({tex,display});return `MATHPLACEHOLDER${n}END`;
 });
 let html=DOMPurify.sanitize(marked.parse(protectedMd,{gfm:true,breaks:false}));
 html=html.replace(/MATHPLACEHOLDER(\d+)END/g,(_,i)=>{const m=maths[+i];return katex.renderToString(m.tex,{displayMode:m.display,throwOnError:false,strict:false,trust:false,output:'htmlAndMathml'});});
 return html;
}
function literalBody(l){
 const chapter=translationCache.get(`${state.mode==='ja'?'ja':'zh'}:${l.chapter}`),item=chapter?.find(x=>x.id===l.id);
 if(!item)return `<div class="translation-loading" role="status">${text('正在載入本章原書譯文…','Loading this chapter’s translation…')}</div>`;
 const intro=`<div class="translation-context"><span class="translation-label">${text('原書忠實翻譯初稿','FAITHFUL TRANSLATION DRAFT')}</span><span>${t('printPage')} ${l.printPage}–${l.printEnd}</span></div>`;
 const chinese=marked.lexer(state.mode==='ja'?item.jaMarkdown:item.zhMarkdown).filter(x=>x.type!=='space').map((token,i)=>`<div class="literal-segment" data-block-id="literal-${i}" lang="${state.mode==='ja'?'ja':'zh-Hant'}">${markdownHtml(token.raw)}</div>`).join('');
 const english=`<div class="original-digital"><p class="small muted">${text('英文為原書擷取文字；公式與排版請開啟原書 PDF 核對。','Extracted original text; use the PDF for faithful equation and page formatting.')}</p><pre lang="en">${esc(item.en)}</pre></div>`;
 return intro+(state.mode==='en'?english:chinese)+(['both','ja'].includes(state.mode)?`<details class="inline-original"><summary>${text('檢視本節完整英文文字','Read this section’s original English text')}</summary>${english}</details>`:'');
}
function literalSection(l){return `<section id="literal-content" class="literal-content content-block" data-block-id="translation"><div class="reading-note">${t('originalGuide')}<br><span class="small">${t('translationNote')}</span></div><div id="literal-body">${literalBody(l)}</div></section>`;}
async function loadChapterTranslation(ch){
 const language=state.mode==='ja'?'ja':'zh',key=`${language}:${ch}`;
 if(translationCache.has(key))return;
 if(!translationRequests.has(key))translationRequests.set(key,(async()=>{
  const response=await fetch(new URL(`./translations/${language==='ja'?'ja/':''}ch${String(ch).padStart(2,'0')}.json`,import.meta.url),{cache:'no-cache'});
  if(!response.ok)throw new Error(`Translation HTTP ${response.status}`);
  let items=await response.json();
  if(language==='ja'){
   let original=translationCache.get(`zh:${ch}`);
   if(!original){const source=await fetch(new URL(`./translations/ch${String(ch).padStart(2,'0')}.json`,import.meta.url));if(!source.ok)throw new Error('Original text unavailable');original=await source.json();translationCache.set(`zh:${ch}`,original);}
   const byId=new Map(original.map(item=>[item.id,item]));items=items.map(item=>({...item,en:byId.get(item.id)?.en||''}));
  }
  translationCache.set(key,items);return items;
 })().catch(error=>{translationRequests.delete(key);throw error;}));
 try{await translationRequests.get(key);if(currentLesson?.chapter===ch&&(state.mode==='ja'?'ja':'zh')===language&&$('#literal-body'))$('#literal-body').innerHTML=literalBody(currentLesson);}
 catch(error){if(currentLesson?.chapter===ch&&(state.mode==='ja'?'ja':'zh')===language&&$('#literal-body')){$('#literal-body').innerHTML=`<div class="notice">${text('譯文暫時無法載入，請重試；原書 PDF 仍可閱讀。','The translation could not load. Retry, or read the original PDF.')} <button id="retry-translation" class="text-button">${text('重試','Retry')}</button></div>`;$('#retry-translation')?.addEventListener('click',()=>loadChapterTranslation(ch));}console.error('Translation loading failed:',error);}
}

function quizCard(l,q,index){const key=`${l.id}::${q.id}`,a=state.attempts[key];const checked=a?.checked,chosen=a?.choice;return `<form class="quiz-card" data-quiz="${esc(q.id)}" data-block-id="quiz-${esc(q.id)}"><div class="block-kicker">${text('理解檢查','CONCEPT CHECK')} ${index+1}</div><div class="quiz-question">${esc(text(q.question.zh,q.question.en))}${state.mode==='both'?`<div class="muted small" lang="en">${esc(q.question.en)}</div>`:''}</div><div class="quiz-options" role="radiogroup" aria-label="${esc(text(q.question.zh,q.question.en))}">${q.options.map((o,i)=>`<label class="quiz-option ${checked&&o.id===q.correct?'correct':checked&&o.id===chosen&&chosen!==q.correct?'incorrect':''}"><input type="radio" name="answer-${esc(q.id)}" value="${esc(o.id)}" ${o.id===chosen?'checked':''}><span class="option-letter">${String.fromCharCode(65+i)}</span><span>${esc(text(o.zh,o.en))}${state.mode==='both'?`<span class="muted small" lang="en" style="display:block">${esc(o.en)}</span>`:''}</span></label>`).join('')}</div>${checked?`<div class="quiz-feedback ${a.correct?'':'try-again'}" role="status"><strong>${a.correct?t('correct'):t('incorrect')}</strong><br>${esc(text(q.explanation.zh,q.explanation.en))}${state.mode==='both'?`<br><span lang="en">${esc(q.explanation.en)}</span>`:''}</div>`:''}<div class="quiz-actions"><button class="primary-button" type="submit">${t('check')}</button><button class="text-button" type="button" data-retry="${esc(q.id)}">${t('retry')}</button></div></form>`;}
function cookieLab(){return `<section class="cookie-lab content-block" data-block-id="cookie-lab"><h3>${text('動手想一想：先驗改變，答案會怎樣？','Try it: what if the prior changes?')}</h3><div class="lab-input"><label for="bowl-prior">${text('選到碗 1 的先驗機率','Prior probability of Bowl 1')}</label><output id="bowl-prior-value">50%</output></div><input id="bowl-prior" type="range" min="0" max="100" value="50"><table class="bayes-table"><thead><tr><th>${text('假設','Hypothesis')}</th><th>${text('先驗','Prior')}</th><th>${text('概似','Likelihood')}</th><th>${text('後驗','Posterior')}</th></tr></thead><tbody id="bowl-table"></tbody></table><p class="lab-result" id="bowl-result" aria-live="polite"></p></section>`;}
function lesson(l){
 const chapter=data.chapters.find(c=>c.id===l.chapter),idx=data.lessons.indexOf(l),prev=data.lessons[idx-1],next=data.lessons[idx+1];
 const notes=`<details id="guide-content" class="supplementary-guide content-block" data-block-id="guide"><summary>${icon('light')} ${text('白話導讀與例子（補充）','Concept notes and examples (supplement)')}</summary><div class="guide-inner">${l.blocks.map((b,i)=>`<section class="content-block" id="block-${esc(b.id)}"><h2>${t(i===0?'intuition':'explanation')}</h2>${bilingual(b)}</section>`).join('')}<section class="example-card"><h3>${t('example')}</h3>${bilingual(l.example)}</section>${l.id==='TB2-CH02-S01'||l.id==='TB2-CH02-S03'?cookieLab():''}${figureFor(l)}</div></details>`;
 const review=l.reviewNote?`<aside class="review-note"><strong>${text('與原文分開的校核註記','Review note, separate from the source')}</strong><br>${esc(text(l.reviewNote.zh,l.reviewNote.en))}</aside>`:'';
 const illustration=visualForLesson(l.id);
 const reading=(illustration?renderVisual(illustration.id,state.mode):'')+literalSection(l)+review+notes+(l.kind==='exercise_index'?exerciseLinks(l.chapter):'');
 const source=sourcePanel(l,currentSourceLoaded);
 return `<div class="page reading-page"><div class="breadcrumbs"><a href="#/map">${t('map')}</a><span>/</span><span>${chapterLabel(l.chapter)}</span></div><div class="lesson-layout ${state.mode==='both'?'parallel':''}"><article class="lesson-article"><header class="lesson-header"><div class="eyebrow">${chapterLabel(l.chapter)} · ${esc(chapterTitle(chapter))}</div><h1>${esc(lessonTitle(l))}</h1><p class="original-title">${esc(state.mode==='en'?l.titleZh:l.titleEn)}</p><div class="lesson-meta"><span class="pill">${t(l.kind==='exercise_index'?'exercise':'guide')}</span><span>${t('printPage')} ${l.printPage}–${l.printEnd}</span><span id="lesson-read-label">${state.read.includes(l.id)?'✓ '+t('completed'):''}</span></div></header><nav class="lesson-tabs" aria-label="${text('本節內容','Section contents')}"><a href="#literal-content" data-scroll="literal-content" class="active">${t('guide')}</a><a href="#source-panel" data-scroll="source-panel" id="source-tab" aria-expanded="${state.sourceOpen===true}">${t('source')}</a>${illustration?`<a href="#visual-${illustration.id}" data-scroll="visual-${illustration.id}">${t('visuals')}</a>`:''}<a href="#quiz-section" data-scroll="quiz-section">${t('quiz')}</a></nav>${state.mode==='both'?`<div class="parallel-columns ${state.sourceOpen?'':'source-is-collapsed'}"><div>${reading}</div>${source}</div>`:reading+source}<section class="quiz-section content-block" id="quiz-section" data-block-id="quiz"><p class="eyebrow">CHECK YOUR UNDERSTANDING</p><h2>${text('讀完之後，試著想一想。','Pause for a quick concept check.')}</h2><p class="quiz-intro">${t('quizIntro')}</p>${l.quiz.length?l.quiz.map((q,i)=>quizCard(l,q,i)).join(''):`<div class="notice">${text('本節原書習題已完整翻譯於上方，原文頁碼入口另列供對照。','The original exercises are translated above; source-page links are provided for comparison.')}</div>`}<p class="quiz-note">${t('quizNote')}</p></section><div class="completion-area content-block" data-block-id="completion"><p>${t('completionNote')}</p><button id="mark-read" class="primary-button" aria-pressed="${state.read.includes(l.id)}">${icon('check')}${state.read.includes(l.id)?t('completed'):t('complete')}</button></div><div class="lesson-navigation">${prev?`<a href="${lessonHref(prev.id)}"><small>${t('previous')}</small>${esc(lessonTitle(prev))}</a>`:'<span></span>'}${next?`<a href="${lessonHref(next.id)}"><small>${t('next')}</small>${esc(lessonTitle(next))}</a>`:'<a href="#/progress">'+t('progress')+'</a>'}</div><p class="content-status">${text('譯文依提供的第二版 PDF 逐段翻譯，保留原書說法；校核註記與本站導讀獨立呈現。圖表與公式排版可隨時開啟 PDF 核對。','The translation follows the supplied second-edition PDF. Source claims are preserved; review notes and supplementary guides are separate. Open the PDF to verify figures and equation layout.')}</p></article><aside class="lesson-rail"><div class="rail-title">${text('閱讀控制','READING CONTROLS','閲覧メニュー')}</div><nav class="rail-list"><a href="#literal-content" data-scroll="literal-content">${t('guide')}</a><a href="#guide-content" data-scroll="guide-content">${text('補充導讀','Concept notes')}</a><a href="#source-panel" data-scroll="source-panel">${text('開啟／關閉原文','Open / close original')}</a>${illustration?`<a href="#visual-${illustration.id}" data-scroll="visual-${illustration.id}">${t('visuals')}</a>`:''}<a href="#quiz-section" data-scroll="quiz-section">${t('quiz')}</a></nav><div class="rail-source">THINK BAYES · 2e<br>Allen B. Downey<br>${t('printPage')} ${l.printPage}<a href="./assets/think-bayes-2e.pdf#page=${l.pdfPage}" target="_blank" rel="noopener">${t('openPdf')}</a></div></aside></div></div>`;
}

function figureFor(l){const f=data.figures.find(f=>f.lessonIds.includes(l.id));if(!f)return '';return `<figure class="figure-card content-block" data-block-id="figure"><button data-figure="${esc(f.id)}" aria-label="${text('放大原書圖表','Enlarge original chart')}"><img loading="lazy" src="${esc(f.file)}" alt="${esc(text(f.captionZh,f.captionEn))}"></button><figcaption>${text('原書圖表','Original chart')} · ${t('printPage')} ${f.printPage} · ${esc(text(f.captionZh,f.captionEn))}<br>Allen B. Downey · CC BY-NC-SA 4.0 · ${text('裁切自原書頁面','cropped from the original page')}</figcaption></figure>`;}
function exerciseLinks(ch){return `<div class="exercise-list">${data.exercises.filter(e=>e.chapter===ch).map(e=>`<a class="exercise-link" href="./assets/think-bayes-2e.pdf#page=${e.pdfPage}" target="_blank" rel="noopener"><span>${t('exercise')} ${esc(e.label)}</span><span class="muted small">${t('printPage')} ${e.printPage}</span></a>`).join('')}</div>`;}

function bindVisualGuides(){
 document.querySelectorAll('[data-enlarge-visual]').forEach(button=>button.addEventListener('click',()=>{
  const dialog=$('#concept-dialog');dialog.setAttribute('aria-label',t('visuals'));dialog.innerHTML=`<div class="concept-dialog-top"><span>${t('visuals')}</span><button id="close-concept" class="source-close-button">${text('✕ 關閉圖解','✕ Close illustration','✕ 図解を閉じる')}</button></div>${renderVisual(button.dataset.enlargeVisual,state.mode,{enlarge:false})}`;
  $('#close-concept').addEventListener('click',()=>dialog.close());dialog.showModal();
 }));
}

function bindLesson(){
 const l=currentLesson;
 document.querySelectorAll('[data-scroll]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();if(a.dataset.scroll==='source-panel'){const opening=!state.sourceOpen;toggleSource(opening);if(opening)$('#source-panel')?.scrollIntoView({behavior:'smooth',block:'start'});return;}if(a.dataset.scroll==='guide-content')$('#guide-content').open=true;document.getElementById(a.dataset.scroll)?.scrollIntoView({behavior:'smooth',block:'start'});}));
 $('#mark-read').addEventListener('click',()=>{if(!state.read.includes(l.id))state.read.push(l.id);save();sidebar();$('#mark-read').innerHTML=icon('check')+t('completed');$('#mark-read').setAttribute('aria-pressed','true');$('#lesson-read-label').textContent='✓ '+t('completed');toast(t('saved'));});
 bindQuizzes();bindSource();loadChapterTranslation(l.chapter);
 if($('#bowl-prior')){const update=()=>{const p=Number($('#bowl-prior').value)/100;const un1=p*.75,un2=(1-p)*.5,z=un1+un2;$('#bowl-prior-value').textContent=Math.round(p*100)+'%';$('#bowl-table').innerHTML=`<tr><td>${text('碗 1','Bowl 1')}</td><td>${p.toFixed(2)}</td><td>0.75</td><td>${(un1/z).toFixed(3)}</td></tr><tr><td>${text('碗 2','Bowl 2')}</td><td>${(1-p).toFixed(2)}</td><td>0.50</td><td>${(un2/z).toFixed(3)}</td></tr>`;$('#bowl-result').textContent=text(`看到香草餅乾後，來自碗 1 的機率為 ${(un1/z*100).toFixed(1)}%。概似維持不變，先驗仍會影響後驗。`,`After observing vanilla, the posterior probability of Bowl 1 is ${(un1/z*100).toFixed(1)}%. The likelihood stays fixed; the prior still affects the posterior.`,`バニラのクッキーを観測した後、ボウル1から来た事後確率は ${(un1/z*100).toFixed(1)}% です。尤度は固定したままでも、事前確率は事後確率に影響します。`);};$('#bowl-prior').addEventListener('input',update);update();}
 document.querySelectorAll('[data-figure]').forEach(b=>b.addEventListener('click',()=>{const f=data.figures.find(x=>x.id===b.dataset.figure);$('#large-image').src=f.file;$('#large-image').alt=text(f.captionZh,f.captionEn);$('#image-caption').textContent=text(f.captionZh,f.captionEn)+` · Think Bayes, p. ${f.printPage} · Allen B. Downey` ;$('#image-dialog').showModal();}));
}
function bindQuizzes(){document.querySelectorAll('form[data-quiz]').forEach(form=>{const q=currentLesson.quiz.find(q=>q.id===form.dataset.quiz),key=`${currentLesson.id}::${q.id}`;form.addEventListener('change',e=>{if(e.target.name?.startsWith('answer-')){const prev=state.attempts[key]||{};state.attempts[key]={...prev,choice:e.target.value,checked:false};save();if(prev.checked)rerenderQuiz(q,form);}});form.addEventListener('submit',e=>{e.preventDefault();const selected=form.querySelector('input:checked');if(!selected){toast(t('selectFirst'));return;}const old=state.attempts[key]||{};state.attempts[key]={...old,choice:selected.value,checked:true,correct:selected.value===q.correct,attemptCount:(old.attemptCount||0)+1,updatedAt:new Date().toISOString()};save();rerenderQuiz(q,form);});form.querySelector('[data-retry]').addEventListener('click',()=>{const old=state.attempts[key]||{};state.attempts[key]={attemptCount:old.attemptCount||0,checked:false};save();rerenderQuiz(q,form);});});}
function rerenderQuiz(q,form){const wrapper=document.createElement('div');wrapper.innerHTML=quizCard(currentLesson,q,currentLesson.quiz.indexOf(q));form.replaceWith(wrapper.firstElementChild);/* Replace listeners only on the replaced form. */const newForm=document.querySelector(`form[data-quiz="${CSS.escape(q.id)}"]`);bindOneQuiz(newForm,q);}
function bindOneQuiz(form,q){const key=`${currentLesson.id}::${q.id}`;form.addEventListener('change',e=>{if(e.target.matches('input[type=radio]')){const old=state.attempts[key]||{};state.attempts[key]={...old,choice:e.target.value,checked:false};save();if(old.checked)rerenderQuiz(q,form);}});form.addEventListener('submit',e=>{e.preventDefault();const selected=form.querySelector('input:checked');if(!selected){toast(t('selectFirst'));return;}const old=state.attempts[key]||{};state.attempts[key]={...old,choice:selected.value,checked:true,correct:selected.value===q.correct,attemptCount:(old.attemptCount||0)+1,updatedAt:new Date().toISOString()};save();rerenderQuiz(q,form);});form.querySelector('[data-retry]').addEventListener('click',()=>{state.attempts[key]={attemptCount:state.attempts[key]?.attemptCount||0,checked:false};save();rerenderQuiz(q,form);});}

async function getPdf(){if(!pdfDocPromise){pdfDocPromise=(async()=>{const lib=await import('./vendor/pdf.mjs');lib.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.mjs',import.meta.url).href;return lib.getDocument({url:new URL('./assets/think-bayes-2e.pdf',import.meta.url).href,useSystemFonts:true,disableFontFace:false}).promise;})().catch(e=>{pdfDocPromise=null;throw e;});}return pdfDocPromise;}
function bindSource(){
 $('#source-toggle')?.addEventListener('click',()=>toggleSource(!state.sourceOpen));
 $('#load-source')?.addEventListener('click',loadSource);
 $('#pdf-prev')?.addEventListener('click',()=>goPdf(pdfPageNumber-1));$('#pdf-next')?.addEventListener('click',()=>goPdf(pdfPageNumber+1));
 $('#pdf-page-input')?.addEventListener('change',e=>{const n=Number(e.target.value);if(!Number.isInteger(n)||n<1||n>304){e.target.value=pdfPageNumber-16;return;}goPdf(n+16);});
 const toolbar=$('.pdf-toolbar');if(toolbar&&!$('#enlarge-source')){const zoom=document.createElement('button');zoom.id='enlarge-source';zoom.textContent=text('放大閱讀','Enlarge page');zoom.addEventListener('click',zoomSource);toolbar.append(zoom);}
 if(state.sourceOpen)loadSource();updatePdfControls();
}
function toggleSource(open){
 state.sourceOpen=!!open;save();
 const body=$('#source-body'),button=$('#source-toggle'),panel=$('#source-panel');
 if(body)body.hidden=!open;
 if(button){button.setAttribute('aria-expanded',String(!!open));button.textContent=open?text('✕ 關閉原文','✕ Close original'):text('展開原文','Open original');}
 panel?.classList.toggle('expanded',!!open);panel?.classList.toggle('collapsed',!open);
 $('#source-tab')?.setAttribute('aria-expanded',String(!!open));$('.parallel-columns')?.classList.toggle('source-is-collapsed',!open);
 if(open)loadSource();else{pdfVersion++;zoomRequest++;if(pdfRenderTask){pdfRenderTask.cancel();pdfRenderTask=null;}button?.focus({preventScroll:true});}
}
function loadSource(){
 if(!state.sourceOpen){toggleSource(true);return;}
 if(!$('#pdf-canvas')){$('#pdf-canvas-host').innerHTML='<canvas id="pdf-canvas" role="img"></canvas>';}
 currentSourceLoaded=true;renderPdf();
}

function goPdf(n){pdfPageNumber=Math.min(320,Math.max(17,n));if(!currentSourceLoaded){loadSource();}else{updatePdfControls();renderPdf();}}
async function zoomSource(){const ticket=++zoomRequest;const button=$('#enlarge-source');if(button)button.disabled=true;try{const doc=await getPdf(),n=pdfPageNumber,page=await doc.getPage(n),base=page.getViewport({scale:1}),viewport=page.getViewport({scale:1400/base.width}),canvas=document.createElement('canvas');canvas.width=Math.floor(viewport.width);canvas.height=Math.floor(viewport.height);await page.render({canvasContext:canvas.getContext('2d'),canvas,viewport}).promise;if(ticket!==zoomRequest||!state.sourceOpen)return;$('#large-image').src=canvas.toDataURL('image/png');$('#large-image').alt=text(`Think Bayes 原書印刷頁 ${n-16}`,`Think Bayes original book page ${n-16}`,`Think Bayes 原書の書籍ページ ${n-16}`);$('#image-caption').textContent=`Think Bayes, 2e · Allen B. Downey · ${t('printPage')} ${n-16} · CC BY-NC-SA 4.0`;$('#image-dialog').showModal();}catch{toast(text('無法放大，請使用原書 PDF 連結。','Could not enlarge this page. Use the original PDF link.'));}finally{if(button?.isConnected)button.disabled=false;}}
function updatePdfControls(){const input=$('#pdf-page-input');if(input)input.value=pdfPageNumber-16;const link=$('#open-source-pdf');if(link)link.href=`./assets/think-bayes-2e.pdf#page=${pdfPageNumber}`;const prev=$('#pdf-prev'),next=$('#pdf-next');if(prev)prev.disabled=pdfPageNumber<=17;if(next)next.disabled=pdfPageNumber>=320;}
async function renderPdf(){const token=++pdfVersion,canvas=$('#pdf-canvas'),host=$('#pdf-canvas-host');if(!canvas||!host||!state.sourceOpen)return;const status=$('#pdf-status');status.textContent=t('loadingPdf');try{const doc=await getPdf();if(token!==pdfVersion||!canvas.isConnected)return;if(pdfRenderTask){pdfRenderTask.cancel();try{await pdfRenderTask.promise;}catch{}pdfRenderTask=null;}const page=await doc.getPage(pdfPageNumber);if(token!==pdfVersion||!canvas.isConnected)return;const base=page.getViewport({scale:1}),width=Math.max(220,Math.min(host.clientWidth-24,1000)),scale=width/base.width,ratio=Math.min(window.devicePixelRatio||1,2),viewport=page.getViewport({scale});canvas.width=Math.floor(viewport.width*ratio);canvas.height=Math.floor(viewport.height*ratio);canvas.style.width=viewport.width+'px';canvas.style.height=viewport.height+'px';canvas.setAttribute('aria-label',text(`Think Bayes 原書印刷頁 ${pdfPageNumber-16}。下方可展開輔助文字。`,`Think Bayes original page ${pdfPageNumber-16}. Extracted reference text is available below.`,`Think Bayes 原書の書籍ページ ${pdfPageNumber-16}。下に補助テキストがあります。`));pdfRenderTask=page.render({canvasContext:canvas.getContext('2d'),canvas,viewport,transform:ratio!==1?[ratio,0,0,ratio,0,0]:null});await pdfRenderTask.promise;if(token===pdfVersion)status.textContent=`Think Bayes · ${t('printPage')} ${pdfPageNumber-16} · ${t('pdfPage')} ${pdfPageNumber} / 338`;}catch(e){if(e?.name==='RenderingCancelledException')return;if(token===pdfVersion&&status.isConnected){status.innerHTML=`${text('原書暫時無法顯示，請使用「開啟原書 PDF」。','Unable to render the page. Use “Open original PDF” instead.')} <button class="text-button" id="retry-pdf">${text('重試','Retry')}</button>`;$('#retry-pdf')?.addEventListener('click',renderPdf);}console.error('PDF rendering failed:',e);}}

async function changeLanguage(mode){if(state.mode===mode)return;if(mode==='ja'){try{document.querySelectorAll('[data-mode]').forEach(b=>b.disabled=true);await loadJapaneseLocale();}catch{toast('日本語の教材を読み込めません。もう一度お試しください。');return;}finally{document.querySelectorAll('[data-mode]').forEach(b=>b.disabled=false);}}const blocks=[...document.querySelectorAll('[data-block-id]')];const anchor=blocks.filter(e=>e.getBoundingClientRect().top<=150).at(-1)||blocks.find(e=>e.getBoundingClientRect().top>=0);const anchorId=anchor?.dataset.blockId,offset=anchor?.getBoundingClientRect().top,oldY=scrollY;state.mode=mode;save();render({preserveScroll:true,preserveSource:true});requestAnimationFrame(()=>{const target=anchorId?document.querySelector(`[data-block-id="${CSS.escape(anchorId)}"]`):null;if(target&&Number.isFinite(offset))window.scrollTo(0,scrollY+target.getBoundingClientRect().top-offset);else window.scrollTo(0,oldY);});}
function glossary(){return `<div class="page"><div class="page-heading"><p class="eyebrow">A SHARED LANGUAGE</p><h1>${t('glossary')}</h1><p>${text('把重要名詞放在同一個地方，隨時回來找。','A shared reference for the ideas you meet across chapters.')}</p></div><input id="glossary-search" class="glossary-search" type="search" placeholder="${text('搜尋中文或英文名詞…','Search a Chinese or English term…')}" aria-label="${text('搜尋概念','Search concepts')}"><div id="glossary-results" class="glossary-grid">${glossaryCards('')}</div></div>`;}
function glossaryCards(query){const items=data.concepts.filter(c=>`${c.titleZh} ${c.titleEn} ${conceptTitle(c)} ${c.definitionZh} ${c.definitionEn} ${text(c.definitionZh,c.definitionEn)}`.toLowerCase().includes(query.toLowerCase()));return items.map(c=>`<article class="glossary-card"><div class="term-title"><h3>${esc(conceptTitle(c))}</h3><span class="pill">${chapterLabel(c.chapter)}</span></div><div class="term-english">${esc(state.mode==='ja'?c.titleEn:text(c.titleEn,c.titleZh))}</div><p>${esc(text(c.definitionZh,c.definitionEn))}</p><a href="${lessonHref(c.lessonId)}">${text('回到概念導讀','Read the concept guide')}</a></article>`).join('')||`<p class="muted">${t('noMatches')}</p>`;}
function validAttempts(){return Object.entries(state.attempts).filter(([key,a])=>{const [id,q]=key.split('::');return data.lessonsById[id]?.quiz.some(x=>x.id===q)&&a?.checked;});}
function progress(){const attempts=validAttempts(),read=state.read.filter(id=>data.lessonsById[id]);return `<div class="page"><div class="page-heading"><p class="eyebrow">YOUR OWN PACE</p><h1>${text('每一點理解，都有留下來。','Every small understanding counts.')}</h1><p>${text('這是你在本機瀏覽器的學習紀錄；已讀與練習表現分開計算。','Your learning record in this browser. Reading and quiz results are counted separately.')}</p></div>${!storageAvailable?`<div class="storage-warning">${text('此瀏覽器無法持久保存資料，請匯出備份。','Persistent storage is unavailable. Please export a backup.')}</div>`:''}<div class="progress-cards"><div class="progress-stat"><strong>${read.length}</strong><span>${text('小節已讀','sections read')} / ${data.lessons.length}</span></div><div class="progress-stat"><strong>${attempts.length}</strong><span>${text('概念題已檢查','questions checked')}</span></div><div class="progress-stat"><strong>${attempts.filter(([,a])=>a.correct).length}</strong><span>${text('目前答對','currently correct')}</span></div></div><div class="button-row"><button id="export-progress" class="secondary-button">${icon('download')}${text('匯出進度','Export progress')}</button><label class="secondary-button" for="import-progress">${text('匯入進度','Import progress')}</label><input id="import-progress" type="file" accept="application/json,.json" hidden></div><div class="section-heading"><h2>${text('最近的練習','Recent practice')}</h2></div>${attempts.length?attempts.sort((a,b)=>String(b[1].updatedAt).localeCompare(String(a[1].updatedAt))).slice(0,30).map(([key,a])=>{const [id]=key.split('::'),l=data.lessonsById[id];return `<div class="attempt-row"><span class="muted small">${chapterLabel(l.chapter)}</span><a href="${lessonHref(id)}">${esc(lessonTitle(l))}</a><span class="result ${a.correct?'':'retry'}">${a.correct?text('已理解','Correct'):text('再練一下','Try again')}</span></div>`;}).join(''):`<div class="empty-state"><h3>${text('從一個小問題開始。','Begin with one small question.')}</h3><p>${text('先讀一節導讀，再試著作答。這裡就會留下你的學習足跡。','Read a concept guide and try its check. Your results will appear here.')}</p><a class="primary-button" href="${lessonHref('TB2-CH02-S01')}">${t('start')}</a></div>`}<div class="section-heading"><h2>${text('各章閱讀進度','Reading by chapter')}</h2></div><div class="chapters-grid">${data.chapters.map(chapterCard).join('')}</div></div>`;}
function bindProgress(){ $('#export-progress').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({format:'bayes-notes-progress',version:1,exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='bayes-notes-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});$('#import-progress').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>5_000_000)throw new Error('too large');const backup=JSON.parse(await file.text());if(backup.format!=='bayes-notes-progress'||backup.version!==1||!backup.state||!Array.isArray(backup.state.read)||!backup.state.attempts||Array.isArray(backup.state.attempts)||typeof backup.state.attempts!=='object')throw new Error('invalid');const s=backup.state;state.read=[...new Set([...state.read,...s.read.filter(id=>typeof id==='string'&&data.lessonsById[id])])];for(const [key,a] of Object.entries(s.attempts)){const [id,qid]=key.split('::');const q=data.lessonsById[id]?.quiz.find(q=>q.id===qid);if(!q||!a||typeof a!=='object')continue;const choice=q.options.some(o=>o.id===a.choice)?a.choice:undefined;if(!choice)continue;const old=state.attempts[key];const date=typeof a.updatedAt==='string'&&!Number.isNaN(Date.parse(a.updatedAt))?a.updatedAt:'1970-01-01T00:00:00Z';if(old?.updatedAt&&old.updatedAt>date)continue;state.attempts[key]={choice,checked:!!a.checked,correct:choice===q.correct,attemptCount:Number.isSafeInteger(a.attemptCount)&&a.attemptCount>=0?a.attemptCount:0,updatedAt:date};}save();render({preserveScroll:true});toast(text('進度已合併匯入。','Progress imported and merged.'));}catch{toast(text('無法讀取這份進度檔，請選擇本站匯出的 JSON。','Could not read this file. Choose a progress JSON exported from this site.'));}});}
function about(){const d=$('#about-dialog');d.innerHTML=`<div class="dialog-top"><h2>${t('attribution')}</h2><button class="icon-button" id="close-about" aria-label="Close">×</button></div><h3>Think Bayes: Bayesian Statistics in Python</h3><p>Allen B. Downey · Second Edition · 2021 · ISBN 9781492089469</p><p>${text('原書正文與本網站依原書改編的教學內容採 CC BY-NC-SA 4.0。請保留作者署名、來源與授權，並註明改動。本站並非作者官方網站，也不表示作者為本站背書。','The book text and adapted educational content use CC BY-NC-SA 4.0. Preserve attribution, source and license links, and indicate modifications. This is an independent learning companion, not an official or endorsed site.')}</p><p><a href="https://allendowney.github.io/ThinkBayes2/" target="_blank" rel="noopener">${text('作者線上版','Author’s online book')}</a> · <a href="https://github.com/AllenDowney/ThinkBayes2" target="_blank" rel="noopener">${text('原書程式與 notebook','Book code and notebooks')}</a> · <a href="https://creativecommons.org/licenses/by-nc-sa/4.0/" target="_blank" rel="noopener">CC BY-NC-SA 4.0</a></p><h3>${text('哪些內容是本站新增的？','What has this site added?')}</h3><p>${text('本站新增中、英、日概念導讀、例子與練習；中文與日文逐段譯文初稿和補充解說分開標示。原文以 PDF 為準，譯文並非作者審核的官方版本。','This site adds Chinese, English and Japanese guides, examples and checks. Chinese and Japanese paragraph translation drafts are separate from supplementary guides. The PDF is the source of record; translations are not author-reviewed official editions.','本サイトは中国語・英語・日本語のガイド、例、理解度チェックを追加しています。中国語・日本語の段落別翻訳初稿と補足解説は区別しています。原文は PDF を基準とし、翻訳は著者監修の公式版ではありません。')}</p><h3>${text('原書版本、翻譯與校訂','Source edition and review notes')}</h3><p>${text('原文以使用者提供的 2021 年第二版 PDF 為基準。作者線上版可能有更新。第 13 章摘要統計、第 16 章資料導向先驗範圍，以及第 19 章 PyMC3 的版本問題，均在相關導讀附註。尚未逐題驗算全部原書程式與習題。','Original pages follow the supplied 2021 second-edition PDF. The online edition may differ. Relevant guides note summary-statistic issues in Chapter 13, data-informed grid ranges in Chapter 16, and the historical PyMC3 version in Chapter 19. Not every original code example or exercise has been independently rerun.')}</p><h3>${text('技術與資料','Technology and data')}</h3><p>${text('進度僅存在你的瀏覽器，沒有帳號、分析追蹤或測驗資料上傳。請以匯出功能備份。','Progress stays in your browser. There are no accounts, analytics trackers, or quiz-data uploads. Use export to back up your progress.')} PDF.js 6.5.438 · Apache-2.0. Marked 18.2.1 · DOMPurify 3.4.18 · KaTeX 0.19.1. ${text('網站程式為 MIT 授權，教材授權另計。','Website code uses MIT; content has its own license.')}</p><p><a href="./CONTENT-LICENSE.txt" target="_blank" rel="noopener">${text('教材授權說明','Content license')}</a> · <a href="./vendor/PDFJS-LICENSE.txt" target="_blank" rel="noopener">PDF.js license</a></p>`;$('#close-about').addEventListener('click',()=>d.close());d.showModal();}

function render(options={}){
 $('#close-image').textContent=text('✕ 關閉原文','✕ Close original','✕ 原文を閉じる');$('#close-image').setAttribute('aria-label',text('關閉原文','Close original','原文を閉じる'));
 $('#sidebar').setAttribute('aria-label',text('課程目錄','Course contents','目次'));$('.skip-link').textContent=text('跳到主要內容','Skip to content','本文へ移動');
 pdfVersion++;if(pdfRenderTask){pdfRenderTask.cancel();pdfRenderTask=null;}
 document.documentElement.lang=state.mode==='en'?'en':state.mode==='ja'?'ja':'zh-Hant';
 if(!options.preserveSource){currentSourceLoaded=false;pdfPageNumber=currentLesson?.pdfPage||33;}
 const wasMenuOpen=$('#sidebar').classList.contains('open');sidebar();if(wasMenuOpen)$('#sidebar').classList.add('open');topbar();footer();
 if(route.name==='lesson'){state.lastLesson=currentLesson.id;save();$('#main').innerHTML=lesson(currentLesson);document.title=`${lessonTitle(currentLesson)} · ${text('貝氏慢學','Bayes Notes')}`;bindLesson();}
 else if(route.name==='home'||route.name==='map'||route.name==='chapters'){$('#main').innerHTML=route.name==='home'?landingPage():learningMap();if(route.name!=='home')bindConnectedMap();document.title=`${text('貝氏慢學','Bayes Notes')} · Bayes, step by step`;}
 else if(route.name==='visuals'){$('#main').innerHTML=visualGallery(state.mode);document.title=`${t('visuals')} · Bayes Notes`;}
 else if(route.name==='glossary'){$('#main').innerHTML=glossary();$('#glossary-search').addEventListener('input',e=>$('#glossary-results').innerHTML=glossaryCards(e.target.value));document.title=`${t('glossary')} · Bayes Notes`;}
 else if(route.name==='progress'){$('#main').innerHTML=progress();bindProgress();document.title=`${t('progress')} · Bayes Notes`;}
 else{$('#main').innerHTML=`<div class="page"><div class="empty-state"><h1>${text('找不到這一節','Section not found')}</h1><p>${text('這個連結可能已改變，請從學習地圖繼續。','This link may have changed. Continue from the learning map.')}</p><a class="primary-button" href="#/chapters">${t('home')}</a></div></div>`;}
 bindVisualGuides();
 if(!options.preserveScroll)window.scrollTo(0,0);
}

$('#close-image').addEventListener('click',()=>{zoomRequest++;$('#image-dialog').close();});
$('#concept-dialog').addEventListener('click',e=>{if(e.target===$('#concept-dialog'))$('#concept-dialog').close();});
$('#image-dialog').addEventListener('click',e=>{if(e.target===$('#image-dialog')){zoomRequest++;$('#image-dialog').close();}});
document.addEventListener('click',e=>{if(document.body.classList.contains('menu-open')&&!e.target.closest('#sidebar')&&!e.target.closest('#menu-toggle')){document.body.classList.remove('menu-open');$('#sidebar').classList.remove('open');$('#menu-toggle')?.setAttribute('aria-expanded','false');}});
window.addEventListener('hashchange',()=>{if(location.hash==='#main'){$('#main').focus();return;}document.body.classList.remove('menu-open');$('#sidebar').classList.remove('open');navigate();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('#image-dialog').open&&!$('#about-dialog').open&&!$('#concept-dialog').open&&state.sourceOpen)toggleSource(false);document.body.classList.remove('menu-open');$('#sidebar').classList.remove('open');$('#menu-toggle')?.setAttribute('aria-expanded','false');}});

try{
 const response=await fetch(new URL('./content.json',import.meta.url),{cache:'no-cache'});if(!response.ok)throw new Error(`Content HTTP ${response.status}`);data=await response.json();data.lessonsById=Object.fromEntries(data.lessons.map(l=>[l.id,l]));if(state.mode==='ja')await loadJapaneseLocale();parseRoute();render();
}catch(e){console.error('Learning site could not load:',e);$('#main').innerHTML='<div class="page"><div class="empty-state"><h1>教材暫時無法載入</h1><p>請確認透過網站網址開啟，而非直接雙擊 HTML。你仍可開啟原書 PDF。</p><p>The learning content could not load. Open this site over HTTP rather than directly from a file.</p><a class="primary-button" href="./assets/think-bayes-2e.pdf">Think Bayes PDF</a></div></div>';}
